Bu program çalışırken (butona basılmıyor) şu olaylar yaşanıyor: 100-200 ms arasında buton basılı tutuluyor, sonra 550-700 ms arasında yeniden basılı tutuluyor. 2 saniyenin sonunda Seri monitörde ne görünür?

```
int sayac = 0;

void setup() {
  pinMode(13, OUTPUT);
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(13, HIGH);
  delay(300);
  digitalWrite(13, LOW);
  delay(300);
  if (digitalRead(2) == LOW) {
    sayac++;
    Serial.print("Basis sayisi: ");
    Serial.println(sayac);
  }
}
```

